using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using MySqlConnector;
namespace WoWItemEditor;
internal sealed record NpcCacheResult(List<QuestNpc> Npcs,DateTime? UpdatedUtc,int Checked,bool Cached);
internal static class NpcCache
{
    internal static string Database=>AppSettings.Current.NpcCacheDatabase;
    private static readonly SemaphoreSlim rebuild=new(1);
    internal static string Key(){var cfg=AppSettings.Current;string Stamp(string path){var f=new FileInfo(path);return f.Exists?$"{f.Length}:{f.LastWriteTimeUtc.Ticks}":"missing";}return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes("npc-v3/"+cfg.Server+"/"+cfg.Port+"/"+cfg.WorldDatabase+"/"+cfg.HotfixDatabase+"/"+cfg.ClientFolder+"/"+Stamp(Path.Combine(cfg.ClientFolder,".build.info"))+"/"+cfg.Db2Folder+"/"+Stamp(Path.Combine(cfg.Db2Folder,"CreatureDisplayInfo.db2")))));}
    internal static async Task Initialize(EditorSettings? settings=null){var cfg=settings??AppSettings.Current;cfg.Validate(false);await using var db=new MySqlConnection(AppSettings.Connection(cfg,cfg.WorldDatabase).ConnectionString);await db.OpenAsync();using(var exists=new MySqlCommand("SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=@name",db)){exists.Parameters.AddWithValue("@name",cfg.NpcCacheDatabase);if(Convert.ToInt32(await exists.ExecuteScalarAsync())==0){try{using var create=new MySqlCommand($"CREATE DATABASE IF NOT EXISTS {cfg.NpcCacheDatabase} CHARACTER SET utf8mb4",db);await create.ExecuteNonQueryAsync();}catch(MySqlException ex) when(ex.Number is 1044 or 1045 or 1142){throw new InvalidOperationException("Cannot create the NPC cache database. Use a MariaDB account allowed to create it, or select a separately provisioned cache database in Settings. No game databases were modified.");}}}
        using var tables=new MySqlCommand($"CREATE TABLE IF NOT EXISTS {cfg.NpcCacheDatabase}.npc_scan_runs(DatasetKey CHAR(64) NOT NULL PRIMARY KEY,UpdatedUtc DATETIME(6) NOT NULL,Checked INT NOT NULL,Accepted INT NOT NULL) ENGINE=InnoDB; CREATE TABLE IF NOT EXISTS {cfg.NpcCacheDatabase}.npc_models(DatasetKey CHAR(64) NOT NULL,NpcId INT NOT NULL,Name VARCHAR(255) NOT NULL,MinLevel INT NOT NULL,MaxLevel INT NOT NULL,FactionId INT NOT NULL,FactionName VARCHAR(255) NOT NULL,SourceJson LONGTEXT NOT NULL,PRIMARY KEY(DatasetKey,NpcId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",db);await tables.ExecuteNonQueryAsync();
    }
    internal static async Task<NpcCacheResult> Load(string? datasetKey=null){await Initialize();using var db=await DatabaseConnection.OpenAsync(Database);string key=datasetKey??Key();using var run=new MySqlCommand("SELECT UpdatedUtc,Checked FROM npc_scan_runs WHERE DatasetKey=@key",db);run.Parameters.AddWithValue("@key",key);DateTime? updated=null;int checkedCount=0;using(var reader=await run.ExecuteReaderAsync())if(await reader.ReadAsync()){updated=DateTime.SpecifyKind(reader.GetDateTime(0),DateTimeKind.Utc);checkedCount=reader.GetInt32(1);}if(updated is null)return new([],null,0,false);using var query=new MySqlCommand("SELECT NpcId,Name,MinLevel,MaxLevel,FactionId,FactionName FROM npc_models WHERE DatasetKey=@key ORDER BY Name,NpcId",db);query.Parameters.AddWithValue("@key",key);var result=new List<QuestNpc>();using(var reader=await query.ExecuteReaderAsync())while(await reader.ReadAsync())result.Add(new(reader.GetInt32(0),reader.GetString(1),reader.GetInt32(2),reader.GetInt32(3),reader.GetInt32(4)){FactionName=reader.GetString(5)});return new(result,updated,checkedCount,true);}
    internal static async Task Invalidate(int id){using var db=await DatabaseConnection.OpenAsync(Database);using var cmd=new MySqlCommand("DELETE FROM npc_models WHERE DatasetKey=@key AND NpcId=@id",db);cmd.Parameters.AddWithValue("@key",Key());cmd.Parameters.AddWithValue("@id",id);await cmd.ExecuteNonQueryAsync();}
    internal static async Task<NpcCacheResult> Rebuild(CatalogResult catalog,Action<QuestNpc?,int,int> progress,CancellationToken cancellation,int limit=int.MaxValue,string? datasetKey=null)
    {
        await rebuild.WaitAsync(cancellation);try{await Initialize();var all=await QuestCreation.Browse();await QuestNpcBrowser.NameFactions(all);var accepted=new List<(QuestNpc Npc,string Source)>();int done=0;foreach(var npc in all.Take(limit)){cancellation.ThrowIfCancellationRequested();QuestNpcSource? source=null;bool valid=false;try{source=await QuestCreation.Source(npc.Id);valid=(await Task.Run(()=>NpcModelBuilder.Build(source,catalog),cancellation)).Count>0;}catch(OperationCanceledException){throw;}catch(MySqlException){throw;}catch{valid=false;}if(valid&&source is not null)accepted.Add((npc,JsonSerializer.Serialize(source)));progress(valid?npc:null,++done,Math.Min(all.Count,limit));}
            cancellation.ThrowIfCancellationRequested();using var db=await DatabaseConnection.OpenAsync(Database);using var tx=await db.BeginTransactionAsync();string key=datasetKey??Key();if(limit!=int.MaxValue&&datasetKey is null)throw new InvalidOperationException("Partial scans must use an isolated test cache key.");if(all.Count>0&&accepted.Count==0)throw new InvalidOperationException("No model loaded successfully. Check the client/data settings; the previous cache was preserved.");using(var clear=new MySqlCommand("DELETE FROM npc_models WHERE DatasetKey=@key",db,tx)){clear.Parameters.AddWithValue("@key",key);await clear.ExecuteNonQueryAsync();}
            foreach(var (npc,source) in accepted){cancellation.ThrowIfCancellationRequested();using var insert=new MySqlCommand("INSERT INTO npc_models(DatasetKey,NpcId,Name,MinLevel,MaxLevel,FactionId,FactionName,SourceJson) VALUES(@key,@id,@name,@min,@max,@faction,@label,@source)",db,tx);insert.Parameters.AddWithValue("@key",key);insert.Parameters.AddWithValue("@id",npc.Id);insert.Parameters.AddWithValue("@name",npc.Name);insert.Parameters.AddWithValue("@min",npc.MinLevel);insert.Parameters.AddWithValue("@max",npc.MaxLevel);insert.Parameters.AddWithValue("@faction",npc.Faction);insert.Parameters.AddWithValue("@label",npc.FactionName);insert.Parameters.AddWithValue("@source",source);await insert.ExecuteNonQueryAsync();}
            using(var run=new MySqlCommand("INSERT INTO npc_scan_runs(DatasetKey,UpdatedUtc,Checked,Accepted) VALUES(@key,UTC_TIMESTAMP(6),@checked,@accepted) ON DUPLICATE KEY UPDATE UpdatedUtc=VALUES(UpdatedUtc),Checked=VALUES(Checked),Accepted=VALUES(Accepted)",db,tx)){run.Parameters.AddWithValue("@key",key);run.Parameters.AddWithValue("@checked",done);run.Parameters.AddWithValue("@accepted",accepted.Count);await run.ExecuteNonQueryAsync();}await tx.CommitAsync();return new(accepted.Select(a=>a.Npc).ToList(),DateTime.UtcNow,done,false);
        }finally{rebuild.Release();}
    }
}
